      adminConnection,
      {
        body: {
          page: 1,
          limit: 10,
        } satisfies IECommerceMallCustomer.IRequest,
      },
    );
  typia.assert(page1);
  // 3. Validate pagination metadata
  TestValidator.equals("current page", page1.pagination.current, 1);
