    page1.data.length,
  );
  // 4. Delete the first address (soft-delete)
  await api.functional.eCommerceMall.customer.addresses.erase(
    customerConnection,
    {
      addressId: address1.id,
    },
  );
  // 5. List addresses again — should contain only the second (default) address
