import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIECommerceMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIECommerceMallAdministrator";
