    "subcategory found in top-level's subcategories",
    foundSubInTop !== undefined,
  );
  typia.assertGuard(foundSubInTop!);
  TestValidator.equals(
    "subcategory name matches",
    foundSubInTop.name,
    "Smartphones",
  );
