export async function test_api_category_search_and_filter(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Join as administrator
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_administrator_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IECommerceMallAdministrator.IJoin,
  });
  // Step 2: Create top-level category 'Electronics'
  const electronics =
    await generate_random_e_commerce_mall_administrator_categories_create(
      adminConnection,
      {
        body: {
          name: "Electronics",
          description: "Electronic devices and gadgets",
        },
      },
    );
  typia.assert(electronics);
  // Step 3: Create top-level category 'Books'
  const books =
    await generate_random_e_commerce_mall_administrator_categories_create(
      adminConnection,
      {
        body: {
          name: "Books",
          description: "All kinds of books",
        },
      },
    );
  typia.assert(books);
  // Step 4: Create subcategory 'Fiction' under 'Books'
  const fiction =
    await generate_random_e_commerce_mall_administrator_categories_create(
      adminConnection,
      {
        body: {
          name: "Fiction",
          description: "Fictional literature",
          parent_id: books.id,
        },
      },
    );
  typia.assert(fiction);
  // Step 5: Search by exact name 'Electronics'
  const searchElectronics =
    await api.functional.eCommerceMall.administrator.categories.index(
      adminConnection,
      {
        body: {
          search: "Electronics",
        } satisfies IECommerceMallCategory.IRequest,
      },
    );
  typia.assert(searchElectronics);
  TestValidator.equals(
    "search by exact name 'Electronics'",
    searchElectronics.data.length,
    1,
  );
  TestValidator.equals(
    "returned category name",
    searchElectronics.data[0]!.name,
    "Electronics",
  );
  // Step 6: Search by partial name 'Book' — should return 'Books' and 'Fiction'
  const searchBook =
    await api.functional.eCommerceMall.administrator.categories.index(
      adminConnection,
      {
        body: {
          search: "Book",
        } satisfies IECommerceMallCategory.IRequest,
      },
    );
  typia.assert(searchBook);
  TestValidator.equals(
    "search by partial name 'Book'",
    searchBook.data.length,
    2,
  );
  TestValidator.predicate(
    "'Books' in partial search results",
    searchBook.data.some((c) => c.name === "Books"),
  );
  TestValidator.predicate(
    "'Fiction' in partial search results (inherited via parent name match or own name match)",
    searchBook.data.some((c) => c.name === "Fiction"),
  );
  // Step 7: Filter by parent_id = null — top-level categories only
  const topLevel =
    await api.functional.eCommerceMall.administrator.categories.index(
      adminConnection,
      {
        body: {
          parent_id: null,
        } satisfies IECommerceMallCategory.IRequest,
      },
    );
  typia.assert(topLevel);
  TestValidator.equals("top-level categories count", topLevel.data.length, 2);
  TestValidator.predicate(
    "'Electronics' is top-level",
    topLevel.data.some((c) => c.name === "Electronics"),
  );
  TestValidator.predicate(
    "'Books' is top-level",
    topLevel.data.some((c) => c.name === "Books"),
  );
  // Step 8: Filter by parent_id = Books' id — subcategories of Books
  const fictionFilter =
    await api.functional.eCommerceMall.administrator.categories.index(
      adminConnection,
      {
        body: {
          parent_id: books.id,
        } satisfies IECommerceMallCategory.IRequest,
      },
    );
  typia.assert(fictionFilter);
  TestValidator.equals(
    "subcategories of Books count",
    fictionFilter.data.length,
    1,
  );
  TestValidator.equals(
    "subcategory name",
    fictionFilter.data[0]!.name,
    "Fiction",
  );
  // Step 9: Pagination test (page=1, limit=1)
  const paginated =
    await api.functional.eCommerceMall.administrator.categories.index(
      adminConnection,
      {
        body: {
          page: 1,
          limit: 1,
        } satisfies IECommerceMallCategory.IRequest,
      },
    );
  typia.assert(paginated);
  TestValidator.equals(
    "pagination: returned 1 record",
    paginated.data.length,
    1,
  );
  TestValidator.predicate(
    "pagination: current page is 1",
    paginated.pagination.current === 1,
  );
  TestValidator.equals("pagination: limit is 1", paginated.pagination.limit, 1);
  TestValidator.predicate(
    "pagination: total records >= 3",
    paginated.pagination.records >= 3,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IECommerceMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IECommerceMallAdministrator";
import type { IECommerceMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IECommerceMallCategory";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIECommerceMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIECommerceMallCategory";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_administrator_join } from "../../../authorize/authorize_administrator_join";
import { authorize_administrator_login } from "../../../authorize/authorize_administrator_login";
import { authorize_administrator_refresh } from "../../../authorize/authorize_administrator_refresh";
import { generate_random_e_commerce_mall_administrator_categories_create } from "../../../generate/generate_random_e_commerce_mall_administrator_categories_create";
import { prepare_random_ecommerce_mall_category } from "../../../prepare/prepare_random_ecommerce_mall_category";

/**
 * Test browsing categories with include_deleted filter for soft-deleted entries.
 *
 * Validates that the administrator category browsing endpoint correctly handles the include_deleted filter. By default, soft-deleted categories are excluded from results. When include_deleted=true is specified, soft-deleted categories appear in results with their deleted_at timestamp populated.
 *
 * The test creates a 'Seasonal' category, soft-deletes it, then verifies its visibility in both filtered modes. It confirms that the deleted category's summary includes all standard fields with a non-null deleted_at value.
 *
 * 1. Register as administrator and acquire authentication tokens.
 * 2. Create a top-level category named 'Seasonal'.
 * 3. Soft-delete the 'Seasonal' category.
 * 4. Browse without include_deleted — verify 'Seasonal' is absent.
 * 5. Browse with include_deleted=true — verify 'Seasonal' is present with non-null deleted_at.
 * 6. Validate all response fields via typia.assert.
 */
export async function test_api_category_browse_including_deleted(
  connection: api.IConnection,
): Promise<void> {
  // 1. Join as administrator
  const adminConnection: api.IConnection = { host: connection.host };
  const admin = await authorize_administrator_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IECommerceMallAdministrator.IJoin,
  });
  typia.assert(admin);
  // 2. Create a category named 'Seasonal'
  const category =
    await generate_random_e_commerce_mall_administrator_categories_create(
      adminConnection,
      {
        body: {
          name: "Seasonal" as any,
        },
      },
    );
  typia.assert(category);
  // 3. Delete the 'Seasonal' category (soft-delete)
  await api.functional.eCommerceMall.administrator.categories.erase(
    adminConnection,
    {
      categoryId: category.id,
    },
  );
  // 4. Browse without include_deleted — 'Seasonal' should NOT be in results
  const withoutDeleted =
    await api.functional.eCommerceMall.administrator.categories.index(
      adminConnection,
      {
        body: {} satisfies IECommerceMallCategory.IRequest,
      },
    );
  typia.assert(withoutDeleted);
  const seasonalWithoutDeleted = withoutDeleted.data.find(
    (c) => c.id === category.id,
  );
  TestValidator.predicate(
    "deleted category excluded without include_deleted",
    () => seasonalWithoutDeleted === undefined,
  );
  // 5. Browse with include_deleted=true — 'Seasonal' should be present
  const withDeleted =
    await api.functional.eCommerceMall.administrator.categories.index(
      adminConnection,
      {
        body: {
          include_deleted: true,
        } satisfies IECommerceMallCategory.IRequest,
      },
    );
  typia.assert(withDeleted);
  const seasonalWithDeleted = withDeleted.data.find(
    (c) => c.id === category.id,
  );
  TestValidator.predicate(
    "deleted category included when include_deleted=true",
    () => seasonalWithDeleted !== undefined,
  );
  // 6. Verify deleted_at is non-null and full structure validates
  const deletedCategory = seasonalWithDeleted!;
  typia.assert(deletedCategory);
  TestValidator.predicate(
    "deleted category has non-null deleted_at timestamp",
    () => deletedCategory.deleted_at !== null,
  );
  TestValidator.predicate(
    "deleted category retains its name",
    () => deletedCategory.name === "Seasonal",
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IECommerceMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IECommerceMallAdministrator";
import type { IECommerceMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IECommerceMallCategory";
import type { IECommerceMallSuperAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IECommerceMallSuperAdministrator";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIECommerceMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIECommerceMallCategory";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_super_administrator_join } from "../../../authorize/authorize_super_administrator_join";
import { authorize_super_administrator_login } from "../../../authorize/authorize_super_administrator_login";
import { authorize_super_administrator_refresh } from "../../../authorize/authorize_super_administrator_refresh";
import { generate_random_e_commerce_mall_super_administrator_categories_create } from "../../../generate/generate_random_e_commerce_mall_super_administrator_categories_create";
import { prepare_random_ecommerce_mall_category } from "../../../prepare/prepare_random_ecommerce_mall_category";

export async function test_api_category_hierarchy_browsing_soft_deleted(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as super administrator
  const superAdminConnection: api.IConnection = { host: connection.host };
  const auth = await authorize_super_administrator_join(
    superAdminConnection,
    {},
  );
  typia.assert(auth);
  // 2. Create a top-level category
  const topLevel =
    await generate_random_e_commerce_mall_super_administrator_categories_create(
      superAdminConnection,
      { body: { parent_id: null } },
    );
  typia.assert(topLevel);
  TestValidator.predicate(
    "top-level category parent is null",
    topLevel.parent === null,
  );
  // 3. Create a subcategory under the top-level category
  const subCategory =
    await generate_random_e_commerce_mall_super_administrator_categories_create(
      superAdminConnection,
      { body: { parent_id: topLevel.id } },
    );
  typia.assert(subCategory);
  TestValidator.predicate(
    "subcategory has a parent",
    subCategory.parent !== null,
  );
  TestValidator.equals(
    "subcategory parent id matches top-level category id",
    subCategory.parent!.id,
    topLevel.id,
  );
  // 4. Soft-delete the subcategory
  await api.functional.eCommerceMall.superAdministrator.categories.erase(
    superAdminConnection,
    { categoryId: subCategory.id },
  );
  // 5. Browse without any filters (default) — only active categories
  const defaultPage =
    await api.functional.eCommerceMall.superAdministrator.categories.index(
      superAdminConnection,
      {
        body: {
          page: 1,
          limit: 100,
        } satisfies IECommerceMallCategory.IRequest,
      },
    );
  typia.assert(defaultPage);
  // Top-level category should be present
  const defaultTopLevel = defaultPage.data.find((c) => c.id === topLevel.id);
  TestValidator.predicate(
    "top-level category present in default browse",
    defaultTopLevel !== undefined,
  );
  // Deleted subcategory should NOT appear
  const defaultDeleted = defaultPage.data.find((c) => c.id === subCategory.id);
  TestValidator.predicate(
    "deleted subcategory absent in default browse",
    defaultDeleted === undefined,
  );
  // 6. Browse with include_deleted=true — deleted subcategory appears
  const includeDeletedPage =
    await api.functional.eCommerceMall.superAdministrator.categories.index(
      superAdminConnection,
      {
        body: {
          include_deleted: true,
          page: 1,
          limit: 100,
        } satisfies IECommerceMallCategory.IRequest,
      },
    );
  typia.assert(includeDeletedPage);
  // Deleted subcategory should now appear
  const foundDeleted = includeDeletedPage.data.find(
    (c) => c.id === subCategory.id,
  );
  TestValidator.predicate(
    "deleted subcategory found with include_deleted=true",
    foundDeleted !== undefined,
  );
  TestValidator.predicate(
    "deleted subcategory has non-null deleted_at",
    foundDeleted!.deleted_at !== null,
  );
  // 7. Browse with include_deleted=false — same as default
  const excludeDeletedPage =
    await api.functional.eCommerceMall.superAdministrator.categories.index(
      superAdminConnection,
      {
        body: {
          include_deleted: false,
          page: 1,
          limit: 100,
        } satisfies IECommerceMallCategory.IRequest,
      },
    );
  typia.assert(excludeDeletedPage);
  const excludeDeleted = excludeDeletedPage.data.find(
    (c) => c.id === subCategory.id,
  );
  TestValidator.predicate(
    "deleted subcategory absent with include_deleted=false",
    excludeDeleted === undefined,
  );
  // 8. Verify hierarchy structure — all records have required fields
  for (const cat of defaultPage.data) {
    TestValidator.predicate(
      `category ${cat.id} has valid id`,
      typeof cat.id === "string",
    );
    TestValidator.predicate(
      `category ${cat.id} has name`,
      typeof cat.name === "string",
    );
    TestValidator.predicate(
      `category ${cat.id} has description`,
      typeof cat.description === "string",
    );
    TestValidator.predicate(
      `category ${cat.id} has created_at`,
      typeof cat.created_at === "string",
    );
    TestValidator.predicate(
      `category ${cat.id} has updated_at`,
      typeof cat.updated_at === "string",
    );
    TestValidator.predicate(
      `category ${cat.id} deleted_at is null or string`,
      cat.deleted_at === null || typeof cat.deleted_at === "string",
    );
    TestValidator.predicate(
      `category ${cat.id} has subcategories array`,
      Array.isArray(cat.subcategories),
    );
  }
  // 9. Verify pagination metadata
  TestValidator.predicate(
    "pagination current >= 1",
    defaultPage.pagination.current >= 1,
  );
  TestValidator.predicate(
    "pagination limit >= 1",
    defaultPage.pagination.limit >= 1,
  );
  TestValidator.predicate(
    "pagination records >= 0",
    defaultPage.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages >= 0",
    defaultPage.pagination.pages >= 0,
  );
  // Verify parent reference hierarchy on the deleted subcategory
  if (foundDeleted) {
    TestValidator.predicate(
      "deleted subcategory has parent reference",
      foundDeleted.parent !== null,
    );
    TestValidator.equals(
      "deleted subcategory parent id matches",
      foundDeleted.parent!.id,
      topLevel.id,
    );
  }
}

