export async function test_api_product_deletion_blocked_by_pending_cancellation(
  connection: api.IConnection,
): Promise<void> {
  //----
  // PREPARE SELLER & PRODUCT
  //----
  // 1. Register seller
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuthd = await authorize_seller_join(sellerConnection, {});
  typia.assert(sellerAuthd);
  // 2. Create product
  const product = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  // 3. Create variant with unique SKU
  const variant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  //----
  // PREPARE CUSTOMER & ORDER
  //----
  // 4. Register customer
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuthd = await authorize_customer_join(customerConnection, {});
  typia.assert(customerAuthd);
  // 5. Create shipping address
  const address =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // 6. Add variant to cart — pass variant.id as product_variant_id
  const cartItem =
    await generate_random_e_commerce_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          product_variant_id: variant.id,
        } satisfies Partial<IECommerceMallCartItem.ICreate>,
      },
    );
  typia.assert(cartItem);
  // 7. Place order
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        addressId: address.id,
      } satisfies Partial<IECommerceMallOrder.ICreate>,
    },
  );
  typia.assert(order);
  // 8. Get order item ID
  const orderItemId = order.orderItems[0].id;
  // 9. Submit cancellation request with a reason
  const cancellationRequest =
    await generate_random_e_commerce_mall_customer_cancellation_requests_create(
      customerConnection,
      {
        body: {
          order_item_id: orderItemId,
          reason: RandomGenerator.paragraph({ sentences: 2 }),
        } satisfies Partial<IECommerceMallCancellationRequest.ICreate>,
      },
    );
  typia.assert(cancellationRequest);
  //----
  // EXECUTION: attempt product deletion
  //----
  // 10. Seller tries to delete product → must be rejected with 409 Conflict
  //     because a pending cancellation request exists for an order item
  //     referencing this product's variant
  await TestValidator.httpError(
    "should reject deletion when pending cancellation request exists",
    409,
    async () => {
      await api.functional.eCommerceMall.seller.products.erase(
        sellerConnection,
        { productId: product.id },
      );
    },
  );
}

