export async function test_api_administrator_product_deletion_with_pending_orders(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register as seller and create product with variant and inventory
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  const product = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  const variant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  await generate_random_e_commerce_mall_seller_products_variants_inventory_create(
    sellerConnection,
    {
      body: {
        quantity_change: 100,
        reason: "seller restock for test",
      },
      params: {
        productId: product.id,
        variantId: variant.id,
      },
    },
  );
  // 2. Register as customer, create address, add to cart, and place order
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  const address =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  await generate_random_e_commerce_mall_customer_cart_items_create(
    customerConnection,
    {
      body: {
        product_variant_id: variant.id,
        quantity: 1,
      },
    },
  );
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        addressId: address.id,
      },
    },
  );
  typia.assert(order);
  // Verify order has items in 'paid' status
  TestValidator.equals("order items count", order.orderItems.length, 1);
  TestValidator.equals(
    "order item status is paid",
    order.orderItems[0].status,
    "paid",
  );
  // 3. Register as administrator and delete the product
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_administrator_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // Administrator should be able to delete despite pending order items
  await api.functional.eCommerceMall.administrator.products.erase(
    adminConnection,
    {
      productId: product.id,
    },
  );
  // 4. Verify the order data remains intact (the deletion succeeded,
  // confirming administrator bypassed seller-specific checks)
  TestValidator.equals(
    "order items count after deletion",
    order.orderItems.length,
    1,
  );
  TestValidator.equals(
    "order item status after deletion",
    order.orderItems[0].status,
    "paid",
  );
}

