/**
 * Test that the administrator product image retrieval endpoint rejects cross-resource access.
 *
 * Validates that GET /eCommerceMall/administrator/products/{productId}/images/{imageId} returns 404 Not Found when the image UUID belongs to a different product than the product UUID path parameter. This ensures the endpoint properly scopes image access to the parent product and prevents information leakage about which parameter is invalid.
 *
 * 1. Authenticate as an administrator via the join endpoint.
 * 2. Authenticate as a seller via the join endpoint.
 * 3. As the seller, create product A.
 * 4. Upload an image to product A — this image belongs exclusively to product A.
 * 5. As the seller, create product B — a separate product with no images.
 * 6. As the administrator, call the endpoint with product B's UUID as productId and product A's image UUID as imageId.
 * 7. Assert that a 404 Not Found HTTP error is thrown, confirming cross-resource access is forbidden.
 */
export async function test_api_administrator_product_image_cross_resource_not_found(
  connection: api.IConnection,
): Promise<void> {
  // 1. Authenticate as administrator
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_administrator_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IECommerceMallAdministrator.IJoin,
  });
  // 2. Authenticate as seller
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      shop_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IECommerceMallSeller.IJoin,
  });
  // 3. Seller creates product A
  const productA = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(productA);
  // 4. Upload an image to product A — this image belongs exclusively to product A
  const imageA =
    await generate_random_e_commerce_mall_seller_products_images_create(
      sellerConnection,
      {
        params: {
          productId: productA.id,
        },
      },
    );
  typia.assert(imageA);
  // 5. Seller creates product B — a separate product with no images
  const productB = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(productB);
  // 6. As administrator, try to access product A's image via product B's ID
  await TestValidator.httpError(
    "cross-resource image access should return 404",
    404,
    async () => {
      await api.functional.eCommerceMall.administrator.products.images.at(
        adminConnection,
        {
          productId: productB.id,
          imageId: imageA.id,
        },
      );
    },
  );
}

