export async function test_api_seller_order_item_cross_seller_access_denied(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Register Seller A
  const sellerAConnection: api.IConnection = { host: connection.host };
  const sellerAAuth = await authorize_seller_join(sellerAConnection, {});
  typia.assert(sellerAAuth);
  // Step 2: Seller A creates a product
  const product = await generate_random_e_commerce_mall_seller_products_create(
    sellerAConnection,
    {},
  );
  typia.assert(product);
  // Step 3: Seller A creates a variant
  const variant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerAConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // Step 4: Seller A adds inventory (restock 100 units to ensure sufficient stock)
  const inventory =
    await generate_random_e_commerce_mall_seller_products_variants_inventory_create(
      sellerAConnection,
      {
        body: {
          quantity_change: 100,
          reason: "restock for testing",
        },
        params: {
          productId: product.id,
          variantId: variant.id,
        },
      },
    );
  typia.assert(inventory);
  // Step 5: Register a customer
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {});
  typia.assert(customerAuth);
  // Step 6: Customer adds variant to cart (quantity 1 to stay within stock)
  const cartItem =
    await generate_random_e_commerce_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          product_variant_id: variant.id,
          quantity: 1,
        },
      },
    );
  typia.assert(cartItem);
  // Step 7: Customer places order capturing the order item belonging to Seller A
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {},
  );
  typia.assert(order);
  const orderItemId: string = order.orderItems[0].id;
  // Step 8: Register Seller B (a different seller)
  const sellerBConnection: api.IConnection = { host: connection.host };
  const sellerBAuth = await authorize_seller_join(sellerBConnection, {});
  typia.assert(sellerBAuth);
  // Step 9: Seller B tries to access Seller A's order item — must be rejected
  await TestValidator.httpError(
    "cross-seller access denied",
    [403, 404],
    async () => {
      await api.functional.eCommerceMall.seller.order_items.at(
        sellerBConnection,
        { itemId: orderItemId },
      );
    },
  );
}

