          product_variant_id: variant.id,
          quantity: 1,
        },
      },
    );
  typia.assert(cartItem);
  // 7. Customer places order (snapshot created at this point)
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {},
  );
  typia.assert(order);
  TestValidator.predicate(
    "order has at least one order item",
    order.orderItems.length >= 1,
  );
  // 8. Seller deletes the product
  await api.functional.eCommerceMall.seller.products.erase(sellerConnection, {
    productId: product.id,
  });
  // 9. Customer retrieves the product-variant snapshot via API
  const snapshot =
    await api.functional.eCommerceMall.customer.order_items.product_snapshot.at(
      customerConnection,
      {
        itemId: order.orderItems[0].id,
      },
    );
  typia.assert(snapshot);
  // Validate snapshot fields match purchase-time state
  TestValidator.equals(
    "product name preserved",
    snapshot.productName,
    product.name,
  );
  TestValidator.equals(
    "product description preserved",
    snapshot.productDescription,
    product.description,
  );
  TestValidator.equals(
    "product base price preserved",
    snapshot.productBasePrice,
    product.base_price,
  );
  TestValidator.equals(
    "variant SKU preserved",
    snapshot.variantSku,
    variant.sku_code,
  );
  TestValidator.predicate(
    "variant options recorded",
    snapshot.variantOptions !== "",
  );
  TestValidator.predicate(
    "created at timestamp exists",
    snapshot.createdAt !== null,
  );
}

