export async function test_api_administrator_order_item_snapshot_preserved_after_product_deletion(
  connection: api.IConnection,
): Promise<void> {
  // 1. Administrator setup
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_administrator_join(adminConnection, {
    body: typia.random<IECommerceMallAdministrator.IJoin>(),
  });
  // 2. Seller setup
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 3. Seller creates product
  const product = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: "Deletable Product",
        description: "Will be deleted",
        base_price: 49.99,
      } satisfies DeepPartial<IECommerceMallProduct.ICreate>,
    },
  );
  typia.assert(product);
  // 4. Seller creates variant
  const variant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          sku_code: "DEL-RED-L",
          price: 59.99,
          options: [
            { key: "color", value: "Red" },
            { key: "size", value: "L" },
          ],
        } satisfies DeepPartial<IECommerceMallProductVariant.ICreate>,
      },
    );
  typia.assert(variant);
  // 5. Seller restocks inventory
  await generate_random_e_commerce_mall_seller_products_variants_inventory_create(
    sellerConnection,
    {
      params: { productId: product.id, variantId: variant.id },
      body: {
        quantity_change: 50,
        reason: "stock",
      } satisfies DeepPartial<IECommerceMallInventoryRecord.ICreate>,
    },
  );
  // 6. Customer setup
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 7. Customer creates address
  const address =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {
        body: {
          recipient_name: "John Doe",
          phone_number: "01012345678",
          street_address: "123 Main St",
          city: "Seoul",
          state_province: "Seoul",
          postal_code: "12345",
          country: "South Korea",
        } satisfies DeepPartial<IECommerceMallCustomerAddress.ICreate>,
      },
    );
  typia.assert(address);
  // 8. Customer adds variant to cart
  await generate_random_e_commerce_mall_customer_cart_items_create(
    customerConnection,
    {
      body: {
        product_variant_id: variant.id,
        quantity: 1,
      } satisfies DeepPartial<IECommerceMallCartItem.ICreate>,
    },
  );
  // 9. Customer places order — snapshot is created here
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        addressId: address.id,
      } satisfies DeepPartial<IECommerceMallOrder.ICreate>,
    },
  );
  typia.assert(order);
  // 10. Extract order item ID
  const orderItemId = order.orderItems[0].id;
  // 11. Seller deletes the product
  await api.functional.eCommerceMall.seller.products.erase(sellerConnection, {
    productId: product.id,
  });
  // 12. Administrator fetches the snapshot
  const snapshot =
    await api.functional.eCommerceMall.administrator.order_items.product_snapshot.at(
      adminConnection,
      { itemId: orderItemId },
    );
  typia.assert(snapshot);
  // 13. Validate snapshot business values
  TestValidator.equals(
    "product name preserved",
    snapshot.productName,
    "Deletable Product",
  );
  TestValidator.equals(
    "product base price preserved",
    snapshot.productBasePrice,
    49.99,
  );
  TestValidator.equals(
    "variant SKU preserved",
    snapshot.variantSku,
    "DEL-RED-L",
  );
  TestValidator.equals("variant price preserved", snapshot.variantPrice, 59.99);
  TestValidator.predicate(
    "product description preserved",
    () => snapshot.productDescription === "Will be deleted",
  );
  TestValidator.predicate(
    "variant options preserved",
    () =>
      snapshot.variantOptions.includes("color") &&
      snapshot.variantOptions.includes("Red") &&
      snapshot.variantOptions.includes("size") &&
      snapshot.variantOptions.includes("L"),
  );
}

