export async function test_api_seller_snapshot_retrieval_by_customer_with_logo(
  connection: api.IConnection,
): Promise<void> {
  //----
  // 1. Seller setup with shop logo
  //----
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      logo_image: `https://example.com/logo/${RandomGenerator.alphaNumeric(8)}.png`,
      shop_name: RandomGenerator.name(),
    },
  });
  const shopName: string = sellerAuth.profile!.shopName;
  // Create a product
  const product = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  // Create a variant (SKU)
  const variant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  // Add inventory stock so the variant is purchasable
  await generate_random_e_commerce_mall_seller_products_variants_inventory_create(
    sellerConnection,
    {
      body: {
        quantity_change: 10,
        reason: "seller restock",
      },
      params: {
        productId: product.id,
        variantId: variant.id,
      },
    },
  );
  //----
  // 2. Customer setup and order placement
  //----
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // Create a shipping address
  const address =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {},
    );
  // Add the variant to the cart
  await generate_random_e_commerce_mall_customer_cart_items_create(
    customerConnection,
    {
      body: {
        product_variant_id: variant.id,
        quantity: 1,
      },
    },
  );
  // Place the order (this auto-generates the seller snapshot)
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        addressId: address.id,
      },
    },
  );
  //----
  // 3. Retrieve and validate seller snapshot
  //----
  const orderItem = order.orderItems[0]!;
  const snapshot =
    await api.functional.eCommerceMall.customer.order_items.seller_snapshot.at(
      customerConnection,
      {
        itemId: orderItem.id,
      },
    );
  typia.assert(snapshot);
  TestValidator.equals(
    "shop_name matches seller's shop name",
    snapshot.shop_name,
    shopName,
  );
  TestValidator.predicate("shop_logo is not null", snapshot.shop_logo !== null);
  TestValidator.predicate(
    "shop_logo is a valid URI",
    typeof snapshot.shop_logo === "string" &&
      snapshot.shop_logo.startsWith("http"),
  );
  TestValidator.predicate(
    "created_at is a valid date-time",
    !Number.isNaN(Date.parse(snapshot.created_at)),
  );
}

