export async function test_api_seller_snapshot_immutable_after_profile_change(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Join as seller with known shop name and logo
  const sellerConnection: api.IConnection = { host: connection.host };
  const originalShopName = RandomGenerator.name();
  const originalLogoImage = typia.random<string & tags.Format<"uri">>();
  const seller = await authorize_seller_join(sellerConnection, {
    body: {
      shop_name: originalShopName,
      logo_image: originalLogoImage,
    },
  });
  typia.assert(seller);
  // Step 2: Create a product
  const product = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  // Step 3: Create a variant
  const variant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // Step 4: Add inventory stock to the variant
  const inventory =
    await generate_random_e_commerce_mall_seller_products_variants_inventory_create(
      sellerConnection,
      {
        params: {
          productId: product.id,
          variantId: variant.id,
        },
      },
    );
  typia.assert(inventory);
  // Step 5: Join as customer
  const customerConnection: api.IConnection = { host: connection.host };
  const customer = await authorize_customer_join(customerConnection, {});
  typia.assert(customer);
  // Step 6: Create a shipping address
  const address =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // Step 7: Add the seller's variant to the customer's cart
  const cartItem =
    await generate_random_e_commerce_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          product_variant_id: variant.id,
          quantity: 1,
        },
      },
    );
  typia.assert(cartItem);
  // Step 8: Place the order — this captures the seller snapshot at purchase time
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        addressId: address.id,
      },
    },
  );
  typia.assert(order);
  // Step 9: Retrieve the seller snapshot via the dedicated endpoint
  const orderItemId = order.orderItems[0]!.id;
  const snapshot =
    await api.functional.eCommerceMall.customer.order_items.seller_snapshot.at(
      customerConnection,
      {
        itemId: orderItemId,
      },
    );
  typia.assert(snapshot);
  // Step 10: Validate the snapshot preserves the original seller profile
  TestValidator.equals(
    "seller snapshot shop_name should match original at purchase time",
    snapshot.shop_name,
    originalShopName,
  );
  TestValidator.equals(
    "seller snapshot shop_logo should match original at purchase time",
    snapshot.shop_logo,
    originalLogoImage,
  );
}

