export async function test_api_seller_snapshot_immutability(
  connection: api.IConnection,
): Promise<void> {
  // ---- Setup connections ----
  const sellerConnection: api.IConnection = { host: connection.host };
  const adminConnection: api.IConnection = { host: connection.host };
  const customerConnection: api.IConnection = { host: connection.host };
  // ---- 1. Seller joins with specific shop name and logo ----
  const originalShopName = RandomGenerator.name();
  const originalLogo = typia.random<string & tags.Format<"uri">>();
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      shop_name: originalShopName,
      logo_image: originalLogo,
    },
  });
  typia.assert(sellerAuth);
  const sellerEmail = sellerAuth.email;
  const sellerPassword = "placeholder";
  // ---- 2. Administrator joins ----
  await authorize_administrator_join(adminConnection, {
    body: typia.random<IECommerceMallAdministrator.IJoin>(),
  });
  // ---- 3. Seller submits approval request ----
  const approvalRequest =
    await api.functional.eCommerceMall.seller.approval_requests.create(
      sellerConnection,
    );
  typia.assert(approvalRequest);
  // ---- 4. Administrator approves the seller ----
  const approved =
    await api.functional.eCommerceMall.administrator.approval_requests.update(
      adminConnection,
      {
        requestId: approvalRequest.id,
        body: {
          status: "approved" as const,
        } satisfies IECommerceMallSellerApprovalRequest.IUpdate,
      },
    );
  typia.assert(approved);
  // ---- 5. Seller creates a product ----
  const product = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  // ---- 6. Seller creates a variant ----
  const variant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // ---- 7. Seller adds inventory stock ----
  const stockQuantity: number & tags.Type<"int32"> & tags.Minimum<1> =
    typia.random<
      number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<500>
    >();
  const inventoryRecord =
    await generate_random_e_commerce_mall_seller_products_variants_inventory_create(
      sellerConnection,
      {
        params: { productId: product.id, variantId: variant.id },
        body: {
          quantity_change: stockQuantity satisfies number as number,
          reason: "Initial stock for testing",
        },
      },
    );
  typia.assert(inventoryRecord);
  // ---- 8. Customer joins ----
  await authorize_customer_join(customerConnection, {});
  // ---- 9. Customer creates a shipping address ----
  const address =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // ---- 10. Customer adds variant to cart ----
  const cartItem =
    await generate_random_e_commerce_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          product_variant_id: variant.id,
          quantity: 1,
        },
      },
    );
  typia.assert(cartItem);
  // ---- 11. Customer places the order (snapshot created with original seller profile) ----
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        addressId: address.id,
      },
    },
  );
  typia.assert(order);
  // ---- 12. Find the order item that references our variant ----
  const orderItem = order.orderItems.find(
    (item) => item.productVariant.sku_code === variant.sku_code,
  );
  typia.assertGuard(orderItem!);
  // ---- 13. Fetch the seller snapshot for the order item ----
  const snapshot =
    await api.functional.eCommerceMall.seller.order_items.seller_snapshot.at(
      sellerConnection,
      {
        itemId: orderItem.id,
      },
    );
  typia.assert(snapshot);
  // ---- 14. Validate snapshot immutability ----
  TestValidator.equals(
    "snapshot shop name",
    snapshot.shop_name,
    originalShopName,
  );
  TestValidator.equals("snapshot logo", snapshot.shop_logo, originalLogo);
  TestValidator.predicate(
    "snapshot created_at reflects order placement time",
    snapshot.created_at <= order.createdAt,
  );
}

