export async function test_api_order_item_status_log_retrieval_after_shipment(
  connection: api.IConnection,
): Promise<void> {
  // 1. Customer joins
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 2. Seller joins
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 3. Seller creates a product
  const product = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  // 4. Seller creates a variant under the product
  const variant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // 5. Seller adds inventory/stock for the variant
  await generate_random_e_commerce_mall_seller_products_variants_inventory_create(
    sellerConnection,
    {
      params: { productId: product.id, variantId: variant.id },
    },
  );
  // 6. Customer creates a shipping address
  const address =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // 7. Customer adds the variant to the shopping cart
  await generate_random_e_commerce_mall_customer_cart_items_create(
    customerConnection,
    {
      body: {
        product_variant_id: variant.id,
      },
    },
  );
  // 8. Customer places the order
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        addressId: address.id,
      },
    },
  );
  typia.assert(order);
  const orderItemId = order.orderItems[0].id;
  const initialStatusLogId = order.orderItems[0].statusLogs[0].id;
  // 9. Seller creates a shipment containing the order item
  // This transitions the item from 'paid' to 'shipped' and creates a new status log
  await generate_random_e_commerce_mall_seller_shipments_create(
    sellerConnection,
    {
      body: {
        orderItemIds: [orderItemId],
      },
    },
  );
  // 10. Customer retrieves the initial status log entry
  const statusLog =
    await api.functional.eCommerceMall.customer.order_items.status_logs.at(
      customerConnection,
      {
        itemId: orderItemId,
        logId: initialStatusLogId,
      },
    );
  typia.assert(statusLog);
  // Validate the status log response
  TestValidator.equals("log ID matches", statusLog.id, initialStatusLogId);
  TestValidator.equals(
    "order item ID matches",
    statusLog.orderItem.id,
    orderItemId,
  );
  TestValidator.equals(
    "initial from_status is null",
    statusLog.from_status,
    null,
  );
  TestValidator.equals(
    "initial to_status is paid",
    statusLog.to_status,
    "paid",
  );
  // Validate timestamps are present and valid
  TestValidator.predicate("created_at is a valid ISO timestamp", () => {
    const parsed = new Date(statusLog.created_at);
    return (
      !isNaN(parsed.getTime()) && parsed.toISOString() === statusLog.created_at
    );
  });
  TestValidator.predicate("updated_at is a valid ISO timestamp", () => {
    const parsed = new Date(statusLog.updated_at);
    return (
      !isNaN(parsed.getTime()) && parsed.toISOString() === statusLog.updated_at
    );
  });
}

