export async function test_api_customer_shipment_view_tracking_in_transit(
  connection: api.IConnection,
): Promise<void> {
  // ---- Prerequisites ----
  // 1. Seller registration
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {});
  typia.assert(sellerAuth);
  const shopName = sellerAuth.profile!.shopName;
  // 2. Seller creates a product
  const product = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  // 3. Seller creates a variant with options
  const variant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          options: [
            { key: "color", value: "Red" },
            { key: "size", value: "Large" },
          ],
        },
      },
    );
  typia.assert(variant);
  // 4. Seller restocks the variant
  const inventory =
    await generate_random_e_commerce_mall_seller_products_variants_inventory_create(
      sellerConnection,
      {
        params: { productId: product.id, variantId: variant.id },
        body: {
          quantity_change: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<100>
          >(),
          reason: "seller restock for test",
        },
      },
    );
  typia.assert(inventory);
  // 5. Customer registration
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {});
  typia.assert(customerAuth);
  // 6. Customer creates a shipping address
  const address =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // 7. Customer adds variant to cart
  const cartItem =
    await generate_random_e_commerce_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          product_variant_id: variant.id,
          quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
          >(),
        },
      },
    );
  typia.assert(cartItem);
  // 8. Customer places the order
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {
      body: { addressId: address.id },
    },
  );
  typia.assert(order);
  // 9. Seller creates a shipment
  const carrierName = RandomGenerator.alphabets(8);
  const trackingNumber = RandomGenerator.alphaNumeric(12);
  const orderItemIds: string[] = order.orderItems.map((item) => item.id);
  const shipment =
    await generate_random_e_commerce_mall_seller_shipments_create(
      sellerConnection,
      {
        body: {
          carrierName,
          trackingNumber,
          orderItemIds,
        },
      },
    );
  typia.assert(shipment);
  // ---- Test execution ----
  // Customer retrieves shipment tracking details
  const shipmentRead = await api.functional.eCommerceMall.customer.shipments.at(
    customerConnection,
    { shipmentId: shipment.id },
  );
  typia.assert(shipmentRead);
  // ---- Business logic validations ----
  TestValidator.equals("shipment id", shipmentRead.id, shipment.id);
  TestValidator.equals("carrier_name", shipmentRead.carrier_name, carrierName);
  TestValidator.equals(
    "tracking_number",
    shipmentRead.tracking_number,
    trackingNumber,
  );
  TestValidator.equals(
    "delivered_at is null (in-transit)",
    shipmentRead.delivered_at,
    null,
  );
  TestValidator.equals(
    "seller shop_name",
    shipmentRead.seller.profile.shop_name,
    shopName,
  );
  TestValidator.predicate(
    "shipmentItems non-empty",
    () => shipmentRead.shipmentItems.length > 0,
  );
  TestValidator.equals(
    "snapshot product name",
    shipmentRead.shipmentItems[0].snapshot.productName,
    product.name,
  );
}

