  typia.assert(order);
  const orderItemIds = order.orderItems.map((item) => item.id);
  // Step 9: Create shipment (seller dispatches the items)
  const shipment =
    await generate_random_e_commerce_mall_seller_shipments_create(
      sellerConnection,
