export async function test_api_cancellation_request_submit_for_paid_item(
  connection: api.IConnection,
): Promise<void> {
  // Create actor-specific connections
  const sellerConnection: api.IConnection = { host: connection.host };
  const customerConnection: api.IConnection = { host: connection.host };
  // 1. Auth as seller
  await authorize_seller_join(sellerConnection, {});
  // 2. Seller creates a product
  const product = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  // 3. Seller creates a variant for the product
  const variant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // 4. Auth as customer
  await authorize_customer_join(customerConnection, {});
  // 5. Customer creates a shipping address
  const address =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // 6. Customer adds the variant to cart with quantity 1
  const cartItem =
    await generate_random_e_commerce_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          product_variant_id: variant.id,
          quantity: 1,
        },
      },
    );
  typia.assert(cartItem);
  // 7. Customer places the order using the created address
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        addressId: address.id,
      },
    },
  );
  typia.assert(order);
  // 8. Extract the first order item (paid status)
  const orderItem = order.orderItems[0];
  typia.assert(orderItem);
  TestValidator.equals("order item status is paid", orderItem.status, "paid");
  // 9. Submit a cancellation request targeting the paid order item
  const cancellationReason = "Changed my mind";
  const cancellation =
    await generate_random_e_commerce_mall_customer_cancellation_requests_create(
      customerConnection,
      {
        body: {
          order_item_id: orderItem.id,
          reason: cancellationReason,
        },
      },
    );
  typia.assert(cancellation);
  // 10. Validate the cancellation request response thoroughly
  TestValidator.equals("status is pending", cancellation.status, "pending");
  TestValidator.equals(
    "orderItem.id matches",
    cancellation.orderItem.id,
    orderItem.id,
  );
  TestValidator.equals(
    "orderItem quantity matches",
    cancellation.orderItem.quantity,
    orderItem.quantity,
  );
  TestValidator.equals(
    "orderItem unit_price matches",
    cancellation.orderItem.unit_price,
    orderItem.unit_price,
  );
  TestValidator.equals(
    "orderItem status is paid",
    cancellation.orderItem.status,
    "paid",
  );
  TestValidator.equals(
    "reason matches input",
    cancellation.reason,
    cancellationReason,
  );
  TestValidator.predicate(
    "customer is populated",
    () => cancellation.customer !== undefined,
  );
  TestValidator.predicate(
    "seller is null (not yet responded)",
    () => cancellation.seller === null,
  );
  TestValidator.predicate(
    "created_at is set",
    () => typeof cancellation.created_at === "string",
  );
  TestValidator.predicate(
    "updated_at is set",
    () => typeof cancellation.updated_at === "string",
  );
  TestValidator.predicate(
    "snapshots is empty array",
    () =>
      Array.isArray(cancellation.snapshots) &&
      cancellation.snapshots.length === 0,
  );
}

