export async function test_api_cancellation_request_approval_by_seller(
  connection: api.IConnection,
): Promise<void> {
  // Store seller credentials for later re-authentication
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  const href = "https://example.com";
  const referrer = "https://example.com";
  //----------------------------------------------------------------//
  // 1. Seller setup: join, create product, variant, and restock
  //----------------------------------------------------------------//
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href,
      referrer,
    },
  });
  const product = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  const variant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // Restock with 100 units
  const inventoryRecord =
    await generate_random_e_commerce_mall_seller_products_variants_inventory_create(
      sellerConnection,
      {
        params: {
          productId: product.id,
          variantId: variant.id,
        },
        body: {
          quantity_change: 100,
          reason: "initial stock",
        },
      },
    );
  typia.assert(inventoryRecord);
  //----------------------------------------------------------------//
  // 2. Customer setup: join, address, cart, order, cancellation
  //----------------------------------------------------------------//
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  const address =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // Add variant to cart with quantity 3
  const cartItem =
    await generate_random_e_commerce_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          product_variant_id: variant.id,
          quantity: 3,
        },
      },
    );
  typia.assert(cartItem);
  // Place the order
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        addressId: address.id,
      },
    },
  );
  typia.assert(order);
  // Get the first (and only) order item
  const orderItem = order.orderItems[0];
  // Submit cancellation request
  const cancellationRequest =
    await generate_random_e_commerce_mall_customer_cancellation_requests_create(
      customerConnection,
      {
        body: {
          order_item_id: orderItem.id,
          reason: "Changed my mind",
        },
      },
    );
  typia.assert(cancellationRequest);
  //----------------------------------------------------------------//
  // 3. Seller approves the cancellation request
  //----------------------------------------------------------------//
  const updatedCancellationRequest =
    await api.functional.eCommerceMall.seller.cancellation_requests.update(
      sellerConnection,
      {
        cancellationRequestId: cancellationRequest.id,
        body: {
          status: "approved",
        } satisfies IECommerceMallCancellationRequest.IUpdate,
      },
    );
  typia.assert(updatedCancellationRequest);
  //----------------------------------------------------------------//
  // 4. Validation checks
  //----------------------------------------------------------------//
  // 4.1. Cancellation request status
  TestValidator.equals(
    "cancellation request status is approved",
    updatedCancellationRequest.status,
    "approved",
  );
  // 4.2. responded_at is populated
  TestValidator.predicate(
    "responded_at is populated after approval",
    updatedCancellationRequest.responded_at !== null,
  );
  // 4.3. Seller info is populated
  TestValidator.predicate(
    "seller is populated after response",
    updatedCancellationRequest.seller !== null,
  );
  // 4.4. Snapshot is created with correct data
  TestValidator.predicate(
    "snapshots array has at least one entry",
    updatedCancellationRequest.snapshots.length > 0,
  );
  const snapshot = updatedCancellationRequest.snapshots[0];
  TestValidator.equals(
    "snapshot reason matches customer's reason",
    snapshot.reason,
    "Changed my mind",
  );
  TestValidator.equals(
    "snapshot status is approved",
    snapshot.status,
    "approved",
  );
  TestValidator.predicate(
    "snapshot has created_at",
    snapshot.created_at !== null && snapshot.created_at !== undefined,
  );
  // 4.5. Order item status changed to cancelled
  TestValidator.equals(
    "order item status changed to cancelled",
    updatedCancellationRequest.orderItem.status,
    "cancelled",
  );
  // 4.6. Stock restored to 100 (was 100 initially, 3 purchased, 3 restored on cancellation)
  TestValidator.equals(
    "stock restored to original 100 after cancellation approval",
    updatedCancellationRequest.orderItem.productVariant.stock,
    100,
  );
}

