export async function test_api_cancellation_request_snapshots_view_after_approval(
  connection: api.IConnection,
): Promise<void> {
  // 1. Administrator joins
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_administrator_join(adminConnection, {
    body: typia.random<IECommerceMallAdministrator.IJoin>(),
  });
  // 2. Seller joins
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuthorized = await authorize_seller_join(sellerConnection, {});
  typia.assert(sellerAuthorized);
  // 3. Seller creates a product
  const product = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  // 4. Seller creates a variant
  const variant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerConnection,
      { params: { productId: product.id } },
    );
  typia.assert(variant);
  // 5. Customer joins
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuthorized = await authorize_customer_join(
    customerConnection,
    {},
  );
  typia.assert(customerAuthorized);
  // 6. Customer creates a shipping address
  const address =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // 7. Customer adds variant to cart
  const cartItem =
    await generate_random_e_commerce_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          product_variant_id: variant.id,
          quantity: 1,
        },
      },
    );
  typia.assert(cartItem);
  // 8. Customer places the order
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        addressId: address.id,
      },
    },
  );
  typia.assert(order);
  // Get the first (and only) order item
  const orderItem = order.orderItems[0]!;
  // 9. Customer submits a cancellation request
  const cancellationReason = RandomGenerator.paragraph({ sentences: 2 });
  const cancellationRequest =
    await generate_random_e_commerce_mall_customer_cancellation_requests_create(
      customerConnection,
      {
        body: {
          order_item_id: orderItem.id,
          reason: cancellationReason,
        },
      },
    );
  typia.assert(cancellationRequest);
  // 10. Seller approves the cancellation request
  const updatedCancellationRequest =
    await api.functional.eCommerceMall.seller.cancellation_requests.update(
      sellerConnection,
      {
        cancellationRequestId: cancellationRequest.id,
        body: {
          status: "approved",
        } satisfies IECommerceMallCancellationRequest.IUpdate,
      },
    );
  typia.assert(updatedCancellationRequest);
  // 11. Retrieve cancellation request snapshots
  const snapshotsPage =
    await api.functional.eCommerceMall.seller.cancellation_requests.snapshots.index(
      sellerConnection,
      {
        cancellationRequestId: cancellationRequest.id,
        body: {},
      },
    );
  typia.assert(snapshotsPage);
  // 12. Validate pagination metadata
  TestValidator.equals(
    "pagination current",
    snapshotsPage.pagination.current,
    1,
  );
  TestValidator.equals("pagination limit", snapshotsPage.pagination.limit, 100);
  TestValidator.predicate(
    "pagination records >= 1",
    snapshotsPage.pagination.records >= 1,
  );
  TestValidator.predicate(
    "pagination pages >= 1",
    snapshotsPage.pagination.pages >= 1,
  );
  // 13. Validate data array is non-empty
  TestValidator.predicate(
    "data array non-empty",
    snapshotsPage.data.length >= 1,
  );
  // 14. Validate each snapshot
  for (const snapshot of snapshotsPage.data) {
    TestValidator.predicate(
      "snapshot id is uuid",
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
        snapshot.id,
      ),
    );
    TestValidator.equals(
      "snapshot reason matches",
      snapshot.reason,
      cancellationReason,
    );
    TestValidator.equals(
      "snapshot status = approved",
      snapshot.status,
      "approved",
    );
    TestValidator.equals(
      "cancellationRequest id",
      snapshot.cancellationRequest.id,
      cancellationRequest.id,
    );
    TestValidator.equals(
      "cancellationRequest status",
      snapshot.cancellationRequest.status,
      "approved",
    );
    TestValidator.predicate(
      "snapshot created_at valid ISO datetime",
      !Number.isNaN(Date.parse(snapshot.created_at)),
    );
  }
  // 15. Verify snapshots are ordered by created_at descending (newest first)
  if (snapshotsPage.data.length >= 2) {
    for (let i = 1; i < snapshotsPage.data.length; i++) {
      const prev = new Date(snapshotsPage.data[i - 1]!.created_at).getTime();
      const curr = new Date(snapshotsPage.data[i]!.created_at).getTime();
      TestValidator.predicate("snapshots ordered newest first", prev >= curr);
    }
  }
}

