export async function test_api_administrator_refund_request_snapshots_list_after_approval(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create administrator account
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_administrator_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IECommerceMallAdministrator.IJoin,
  });
  // 2. Create seller account
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuthorized = await authorize_seller_join(sellerConnection, {});
  typia.assert(sellerAuthorized);
  // 3. Seller creates a product
  const product = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  // 4. Seller creates a variant (SKU)
  const variant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // 5. Seller restocks variant with positive quantity
  const inventoryRecord =
    await generate_random_e_commerce_mall_seller_products_variants_inventory_create(
      sellerConnection,
      {
        params: { productId: product.id, variantId: variant.id },
        body: {
          quantity_change: 100,
          reason: "Initial restock for E2E test",
        },
      },
    );
  typia.assert(inventoryRecord);
  // 6. Create customer account
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuthorized = await authorize_customer_join(
    customerConnection,
    {},
  );
  typia.assert(customerAuthorized);
  // 7. Customer creates a shipping address
  const address =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // 8. Customer adds variant to cart
  const cartItem =
    await generate_random_e_commerce_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          product_variant_id: variant.id,
          quantity: 2,
        },
      },
    );
  typia.assert(cartItem);
  // 9. Customer places the order
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        addressId: address.id,
      },
    },
  );
  typia.assert(order);
  const orderItem = order.orderItems[0]!;
  // 10. Seller creates a shipment (reuse existing sellerConnection)
  const shipment =
    await generate_random_e_commerce_mall_seller_shipments_create(
      sellerConnection,
      {
        body: {
          orderItemIds: [orderItem.id],
          carrierName: "Test Carrier",
          trackingNumber: `TRACK-${RandomGenerator.alphaNumeric(8)}`,
        },
      },
    );
  typia.assert(shipment);
  // 11. Customer confirms delivery
  const confirmedShipment =
    await api.functional.eCommerceMall.customer.shipments.confirm_delivery.confirmDelivery(
      customerConnection,
      {
        shipmentId: shipment.id,
      },
    );
  typia.assert(confirmedShipment);
  // 12. Customer creates a refund request
  const refundRequestReason = "Product is defective";
  const refundRequest =
    await generate_random_e_commerce_mall_customer_refund_requests_create(
      customerConnection,
      {
        body: {
          orderItemId: orderItem.id,
          reason: refundRequestReason,
        },
      },
    );
  typia.assert(refundRequest);
  // 13. Seller approves the refund request (creates snapshot)
  const updatedRefundRequest =
    await api.functional.eCommerceMall.seller.refund_requests.update(
      sellerConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          status: "approved",
        } satisfies IECommerceMallRefundRequest.IUpdate,
      },
    );
  typia.assert(updatedRefundRequest);
  // 14. Administrator lists refund request snapshots
  const page =
    await api.functional.eCommerceMall.administrator.refund_requests.snapshots.index(
      adminConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          page: 1,
          limit: 10,
        } satisfies IECommerceMallRefundRequestSnapshot.IRequest,
      },
    );
  typia.assert(page);
  // 15. Validate pagination metadata
  TestValidator.equals("pagination current page", page.pagination.current, 1);
  TestValidator.equals("pagination limit", page.pagination.limit, 10);
  TestValidator.predicate(
    "pagination has at least one record",
    () => page.pagination.records >= 1,
  );
  TestValidator.predicate(
    "pagination has at least one page",
    () => page.pagination.pages >= 1,
  );
  // 16. Validate snapshot business logic (not type validation)
  const snapshot = page.data[0]!;
  TestValidator.equals(
    "snapshot reason matches customer's original request",
    snapshot.reason,
    refundRequestReason,
  );
  TestValidator.equals(
    "snapshot status reflects seller approval",
    snapshot.status,
    "approved",
  );
  // 17. Validate sorting (newest first) - only check if more than one snapshot
  if (page.data.length > 1) {
    for (let i = 1; i < page.data.length; i++) {
      TestValidator.predicate(
        `snapshot at index ${i} is not newer than previous`,
        () =>
          new Date(page.data[i]!.created_at).getTime() <=
          new Date(page.data[i - 1]!.created_at).getTime(),
      );
    }
  }
}

