export async function test_api_seller_refund_request_snapshot_retrieval_after_rejection(
  connection: api.IConnection,
): Promise<void> {
  // ---- Actor Connections ----
  const sellerConnection: api.IConnection = { host: connection.host };
  const customerConnection: api.IConnection = { host: connection.host };
  // ---- 1. Seller Join ----
  await authorize_seller_join(sellerConnection, {});
  // ---- 2. Seller creates product ----
  const product = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  // ---- 3. Seller creates variant ----
  const variant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // ---- 4. Seller restocks variant ----
  await generate_random_e_commerce_mall_seller_products_variants_inventory_create(
    sellerConnection,
    {
      params: {
        productId: product.id,
        variantId: variant.id,
      },
      body: {
        quantity_change: 100,
        reason: "initial restock",
      },
    },
  );
  // ---- 5. Customer join ----
  await authorize_customer_join(customerConnection, {});
  // ---- 6. Customer creates address ----
  const address =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // ---- 7. Customer adds variant to cart ----
  await generate_random_e_commerce_mall_customer_cart_items_create(
    customerConnection,
    {
      body: {
        product_variant_id: variant.id,
        quantity: 1,
      },
    },
  );
  // ---- 8. Customer places order ----
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        addressId: address.id,
      },
    },
  );
  typia.assert(order);
  const orderItemId = order.orderItems[0].id;
  // ---- 9. Seller creates shipment ----
  const shipment =
    await generate_random_e_commerce_mall_seller_shipments_create(
      sellerConnection,
      {
        body: {
          orderItemIds: [orderItemId],
          carrierName: RandomGenerator.name(),
          trackingNumber: RandomGenerator.alphaNumeric(12),
        },
      },
    );
  typia.assert(shipment);
  // ---- 10. Customer confirms delivery ----
  const confirmedShipment =
    await api.functional.eCommerceMall.customer.shipments.confirm_delivery.confirmDelivery(
      customerConnection,
      {
        shipmentId: shipment.id,
      },
    );
  typia.assert(confirmedShipment);
  // ---- 11. Customer creates refund request with reason "Changed my mind" ----
  const refundRequest =
    await generate_random_e_commerce_mall_customer_refund_requests_create(
      customerConnection,
      {
        body: {
          orderItemId: orderItemId,
          reason: "Changed my mind",
        },
      },
    );
  typia.assert(refundRequest);
  // ---- 12. Seller rejects the refund request ----
  const updatedRefundRequest =
    await api.functional.eCommerceMall.seller.refund_requests.update(
      sellerConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          status: "rejected",
        },
      },
    );
  typia.assert(updatedRefundRequest);
  const snapshotId = updatedRefundRequest.refundRequestSnapshots[0].id;
  // ---- 13. Seller retrieves the snapshot ----
  const snapshot =
    await api.functional.eCommerceMall.seller.refund_requests.snapshots.at(
      sellerConnection,
      {
        refundRequestId: refundRequest.id,
        snapshotId: snapshotId,
      },
    );
  typia.assert(snapshot);
  // ---- 14. Validate snapshot contents ----
  TestValidator.equals(
    "snapshot id matches requested",
    snapshot.id,
    snapshotId,
  );
  TestValidator.equals(
    "snapshot reason is customer's original reason",
    snapshot.reason,
    "Changed my mind",
  );
  TestValidator.equals(
    "snapshot status is rejected",
    snapshot.status,
    "rejected",
  );
  TestValidator.equals(
    "snapshot refundRequest id matches",
    snapshot.refundRequest.id,
    refundRequest.id,
  );
}

