export async function test_api_review_duplicate_review_rejection(
  connection: api.IConnection,
): Promise<void> {
  //----
  // 1. Seller setup
  //----
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerEmail: string = typia.random<string & tags.Format<"email">>();
  const sellerPassword: string = RandomGenerator.alphaNumeric(16);
  await authorize_seller_join(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    },
  });
  // 2. Create product
  const product = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  // 3. Create variant
  const variant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // 4. Restock inventory (positive quantity_change = restock)
  await generate_random_e_commerce_mall_seller_products_variants_inventory_create(
    sellerConnection,
    {
      params: { productId: product.id, variantId: variant.id },
      body: { quantity_change: 100, reason: "restock for test" },
    },
  );
  //----
  // 5. Customer setup
  //----
  const customerConnection: api.IConnection = { host: connection.host };
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customerPassword: string = RandomGenerator.alphaNumeric(16);
  await authorize_customer_join(customerConnection, {
    body: {
      email: customerEmail,
      password: customerPassword,
    },
  });
  // 6. Create shipping address
  const address =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // 7. Add variant to cart
  await generate_random_e_commerce_mall_customer_cart_items_create(
    customerConnection,
    {
      body: { product_variant_id: variant.id },
    },
  );
  // 8. Place order
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {
      body: { addressId: address.id },
    },
  );
  typia.assert(order);
  const orderItemId: string = order.orderItems[0].id;
  //----
  // 9. Seller: re-login and create shipment
  //----
  const sellerLoginConnection: api.IConnection = { host: connection.host };
  await authorize_seller_login(sellerLoginConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  const shipment =
    await generate_random_e_commerce_mall_seller_shipments_create(
      sellerLoginConnection,
      {
        body: { orderItemIds: [orderItemId] },
      },
    );
  typia.assert(shipment);
  //----
  // 10. Customer: re-login and confirm delivery
  //----
  const customerLoginConnection: api.IConnection = { host: connection.host };
  await authorize_customer_login(customerLoginConnection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  await api.functional.eCommerceMall.customer.shipments.confirm_delivery.confirmDelivery(
    customerLoginConnection,
    { shipmentId: shipment.id },
  );
  //----
  // 11. Submit first review (should succeed)
  //----
  const firstReview =
    await api.functional.eCommerceMall.customer.reviews.create(
      customerLoginConnection,
      {
        body: {
          order_item_id: orderItemId,
          rating: 5,
          content: "First review",
        } satisfies IECommerceMallReview.ICreate,
      },
    );
  typia.assert(firstReview);
  //----
  // 12. Submit second review for same order_item_id (should fail)
  //----
  await TestValidator.httpError("duplicate review rejection", 422, async () => {
    await api.functional.eCommerceMall.customer.reviews.create(
      customerLoginConnection,
      {
        body: {
          order_item_id: orderItemId,
          rating: 3,
          content: "Second attempt",
        } satisfies IECommerceMallReview.ICreate,
      },
    );
  });
  //----
  // 13. Verify first review remains intact
  //----
  TestValidator.equals("first review rating", firstReview.rating, 5);
  TestValidator.equals(
    "first review content",
    firstReview.content,
    "First review",
  );
}

