export async function test_api_review_rating_only_update(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create customer account
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 2. Create seller account
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 3. Seller creates a product
  const product = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  // 4. Seller creates a variant under the product
  const variant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // 5. Customer creates a shipping address
  const address =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // 6. Customer adds the variant to cart
  await generate_random_e_commerce_mall_customer_cart_items_create(
    customerConnection,
    {
      body: {
        product_variant_id: variant.id,
        quantity: 1,
      },
    },
  );
  // 7. Customer places an order
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        addressId: address.id,
      },
    },
  );
  typia.assert(order);
  // Get the order item
  const orderItem = order.orderItems[0];
  // 8. Seller creates a shipment for the paid order items
  const shipment =
    await generate_random_e_commerce_mall_seller_shipments_create(
      sellerConnection,
      {
        body: {
          orderItemIds: [orderItem.id],
        },
      },
    );
  typia.assert(shipment);
  // 9. Customer confirms delivery
  await api.functional.eCommerceMall.customer.shipments.confirm_delivery.confirmDelivery(
    customerConnection,
    {
      shipmentId: shipment.id,
    },
  );
  // 10. Customer creates an initial review with rating 4 and text content
  const reviewContent =
    "This product is quite good overall, but I will reconsider.";
  const initialReview =
    await generate_random_e_commerce_mall_customer_reviews_create(
      customerConnection,
      {
        body: {
          order_item_id: orderItem.id,
          rating: 4,
          content: reviewContent,
        },
      },
    );
  typia.assert(initialReview);
  // Capture original timestamps for validation
  const originalCreatedAt = initialReview.created_at;
  const originalUpdatedAt = initialReview.updated_at;
  // 11. Customer updates the review - rating only, change to 2
  const updatedReview =
    await api.functional.eCommerceMall.customer.reviews.update(
      customerConnection,
      {
        reviewId: initialReview.id,
        body: {
          rating: 2,
        } satisfies IECommerceMallReview.IUpdate,
      },
    );
  typia.assert(updatedReview);
  // Validation point (1): Rating is updated to the new value (2)
  TestValidator.equals("rating updated to 2", updatedReview.rating, 2);
  // Validation point (5): Text content remains unchanged from the original
  TestValidator.equals(
    "text content unchanged",
    updatedReview.content,
    reviewContent,
  );
  // Validation point (3): created_at timestamp remains unchanged (preserving sort position)
  TestValidator.equals(
    "created_at unchanged",
    updatedReview.created_at,
    originalCreatedAt,
  );
  // Validation point (4): updated_at timestamp is refreshed
  TestValidator.predicate(
    "updated_at refreshed",
    () => updatedReview.updated_at > originalUpdatedAt,
  );
}

