export async function test_api_review_deletion_already_deleted(
  connection: api.IConnection,
): Promise<void> {
  // 1. Setup seller
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 2. Create product
  const product = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  // 3. Create variant with at least one option
  const variant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // 4. Setup customer
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 5. Create a shipping address
  const address =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // 6. Add variant to cart
  await generate_random_e_commerce_mall_customer_cart_items_create(
    customerConnection,
    {
      body: {
        product_variant_id: variant.id,
        quantity: 1,
      },
    },
  );
  // 7. Place order using the created address
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        addressId: address.id,
      },
    },
  );
  typia.assert(order);
  // 8. Get the first order item
  const orderItem = order.orderItems[0];
  typia.assert(orderItem);
  // 9. Create a review for the delivered order item
  const review = await generate_random_e_commerce_mall_customer_reviews_create(
    customerConnection,
    {
      body: {
        order_item_id: orderItem.id,
        rating: 5,
        content: "Great product!",
      },
    },
  );
  typia.assert(review);
  // 10. First deletion: should succeed (returns void)
  await api.functional.eCommerceMall.customer.reviews.erase(
    customerConnection,
    { reviewId: review.id },
  );
  // 11. Second deletion: should fail with 410 Gone
  await TestValidator.httpError(
    "deleting already deleted review",
    410,
    async () => {
      await api.functional.eCommerceMall.customer.reviews.erase(
        customerConnection,
        { reviewId: review.id },
      );
    },
  );
}

