export async function test_api_review_snapshot_after_edit(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create actor-specific connections
  const sellerConnection: api.IConnection = { host: connection.host };
  const customerConnection: api.IConnection = { host: connection.host };
  // 2. Authenticate seller
  await authorize_seller_join(sellerConnection, {});
  // 3. Authenticate customer
  await authorize_customer_join(customerConnection, {});
  // 4. Seller creates a product
  const product: IECommerceMallProduct =
    await generate_random_e_commerce_mall_seller_products_create(
      sellerConnection,
      {},
    );
  typia.assert(product);
  // 5. Seller creates a variant under the product
  const variant: IECommerceMallProductVariant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // 6. Customer creates a shipping address
  const address: IECommerceMallCustomerAddress =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  // 7. Customer adds the variant to cart
  const cartItem: IECommerceMallCartItem =
    await generate_random_e_commerce_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          product_variant_id: variant.id,
          quantity: 1,
        },
      },
    );
  typia.assert(cartItem);
  // 8. Customer places an order
  const order: IECommerceMallOrder =
    await generate_random_e_commerce_mall_customer_orders_create(
      customerConnection,
      {
        body: {
          addressId: address.id,
        },
      },
    );
  typia.assert(order);
  // 9. Get the order item from the order
  const orderItem: IECommerceMallOrderItem = order.orderItems[0];
  typia.assert(orderItem);
  // 10. Customer writes a review with controlled values
  const review: IECommerceMallReview =
    await api.functional.eCommerceMall.customer.reviews.create(
      customerConnection,
      {
        body: {
          order_item_id: orderItem.id,
          rating: 3,
          content: "Good product",
        } satisfies IECommerceMallReview.ICreate,
      },
    );
  typia.assert(review);
  TestValidator.equals("initial review rating", review.rating, 3);
  TestValidator.equals(
    "initial review content",
    review.content,
    "Good product",
  );
}

