export async function test_api_admin_force_refund_paid_order_item(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_administrator_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IECommerceMallAdministrator.IJoin,
  });
  // 2. Seller setup
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 3. Seller creates product
  const product = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  // 4. Seller creates variant
  const variant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // 5. Seller adds stock (100 units)
  await generate_random_e_commerce_mall_seller_products_variants_inventory_create(
    sellerConnection,
    {
      body: {
        quantity_change: 100,
        reason: "initial stock",
      },
      params: {
        productId: product.id,
        variantId: variant.id,
      },
    },
  );
  // 6. Customer setup
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 7. Customer creates shipping address
  const address =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {
        body: { is_default: true },
      },
    );
  typia.assert(address);
  // 8. Customer adds variant to cart (quantity: 3)
  const cartItem =
    await generate_random_e_commerce_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          product_variant_id: variant.id,
          quantity: 3,
        },
      },
    );
  typia.assert(cartItem);
  // 9. Customer places order
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        addressId: address.id,
      },
    },
  );
  typia.assert(order);
  // Capture the first order item (status should be 'paid')
  const orderItem = order.orderItems[0]!;
  TestValidator.equals("order item status is paid", orderItem.status, "paid");
  const stockBeforeRefund = orderItem.productVariant.stock;
  // 10. Administrator force-refunds the paid order item
  const refundedItem =
    await api.functional.eCommerceMall.administrator.order_items.force_refund.create(
      adminConnection,
      {
        itemId: orderItem.id,
      },
    );
  typia.assert(refundedItem);
  // 11. Validations
  TestValidator.equals(
    "status changed to refunded",
    refundedItem.status,
    "refunded",
  );
  TestValidator.predicate(
    "updated_at is after created_at",
    () =>
      new Date(refundedItem.updated_at).getTime() >
      new Date(refundedItem.created_at).getTime(),
  );
  // Check that a status log was created with reason 'administrator_force_refund'
  const forceRefundLog = refundedItem.statusLogs.find(
    (log) => log.reason === "administrator_force_refund",
  );
  TestValidator.equals(
    "status log with reason exists",
    forceRefundLog != null,
    true,
  );
  typia.assertGuard(forceRefundLog!);
  TestValidator.equals(
    "from_status is paid",
    forceRefundLog!.from_status,
    "paid",
  );
  TestValidator.equals(
    "to_status is refunded",
    forceRefundLog!.to_status,
    "refunded",
  );
  // Verify stock restored by the ordered quantity (3)
  TestValidator.equals(
    "stock restored by quantity",
    refundedItem.productVariant.stock,
    stockBeforeRefund + 3,
  );
}

