        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  await generate_random_e_commerce_mall_seller_products_variants_inventory_create(
    sellerConnection,
    {
      params: { productId: product.id, variantId: variant.id },
      body: {
        quantity_change: 10,
        reason: "seller restock",
      },
    },
  );
  // Step 2: Customer setup - create address, add to cart, place order
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = RandomGenerator.alphaNumeric(16);
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {
    body: {
      email: customerEmail,
      password: customerPassword,
    },
  });
  const address =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  await generate_random_e_commerce_mall_customer_cart_items_create(
    customerConnection,
    {
      body: {
        product_variant_id: variant.id,
        quantity: 1,
      },
    },
  );
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        addressId: address.id,
      },
    },
  );
  typia.assert(order);
  const orderItem = order.orderItems[0];
  typia.assert(orderItem);
  TestValidator.equals("order item status is paid", orderItem.status, "paid");
  // Step 3: Seller creates shipment to mark item as shipped
  const sellerLoginConnection: api.IConnection = { host: connection.host };
  await authorize_seller_login(sellerLoginConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  const shipment: IECommerceMallShipment =
    await generate_random_e_commerce_mall_seller_shipments_create(
      sellerLoginConnection,
      {
        body: {
          orderItemIds: [orderItem.id],
          carrierName: RandomGenerator.name(),
          trackingNumber: RandomGenerator.alphaNumeric(10),
        },
      },
    );
  typia.assert(shipment);
  // Step 4: Customer confirms delivery
  const customerLoginConnection: api.IConnection = { host: connection.host };
  await authorize_customer_login(customerLoginConnection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  const deliveredShipment: IECommerceMallShipment =
    await api.functional.eCommerceMall.customer.shipments.confirm_delivery.confirmDelivery(
      customerLoginConnection,
      {
        shipmentId: shipment.id,
      },
    );
  typia.assert(deliveredShipment);
  // Step 5: Super administrator force-refunds the delivered order item
  const superAdminConnection: api.IConnection = { host: connection.host };
  await authorize_super_administrator_join(superAdminConnection, {});
  const refundedItem: IECommerceMallOrderItem =
    await api.functional.eCommerceMall.superAdministrator.order_items.force_refund.create(
      superAdminConnection,
      {
        itemId: orderItem.id,
      },
    );
  typia.assert(refundedItem);
  // Validations
  TestValidator.equals(
    "order item status changed to refunded",
    refundedItem.status,
    "refunded",
  );
  const statusLog = refundedItem.statusLogs.find(
    (log) => log.to_status === "refunded",
  );
  typia.assert(statusLog!);
  TestValidator.equals(
    "status log from_status is delivered",
    statusLog!.from_status,
    "delivered",
  );
  TestValidator.equals(
    "status log reason is administrator_force_refund",
    statusLog!.reason,
    "administrator_force_refund",
  );
}

