export async function test_api_super_administrator_force_refund_rejected_for_cancelled_item(
  connection: api.IConnection,
): Promise<void> {
  // ---- Step 1: Seller creates product with variant and stock ----
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  const product = await generate_random_e_commerce_mall_seller_products_create(
    sellerConnection,
    {},
  );
  typia.assert(product);
  const variant =
    await generate_random_e_commerce_mall_seller_products_variants_create(
      sellerConnection,
      { params: { productId: product.id } },
    );
  typia.assert(variant);
  await generate_random_e_commerce_mall_seller_products_variants_inventory_create(
    sellerConnection,
    {
      params: { productId: product.id, variantId: variant.id },
      body: {
        quantity_change: 100,
        reason: "Initial restock for E2E test",
      },
    },
  );
  // ---- Step 2: Customer places order ----
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  const address =
    await generate_random_e_commerce_mall_customer_addresses_create(
      customerConnection,
      {},
    );
  typia.assert(address);
  await generate_random_e_commerce_mall_customer_cart_items_create(
    customerConnection,
    {
      body: {
        product_variant_id: variant.id,
        quantity: 1,
      },
    },
  );
  const order = await generate_random_e_commerce_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        addressId: address.id,
      },
    },
  );
  typia.assert(order);
  const orderItem = order.orderItems[0]!;
  // ---- Step 3: Customer requests cancellation ----
  const cancellationRequest =
    await generate_random_e_commerce_mall_customer_cancellation_requests_create(
      customerConnection,
      {
        body: {
          order_item_id: orderItem.id,
          reason: "Changed my mind about this purchase",
        },
      },
    );
  typia.assert(cancellationRequest);
  // ---- Step 4: Seller approves cancellation (item becomes 'cancelled') ----
  const approvedCancellation =
    await api.functional.eCommerceMall.seller.cancellation_requests.update(
      sellerConnection,
      {
        cancellationRequestId: cancellationRequest.id,
        body: {
          status: "approved",
        } satisfies IECommerceMallCancellationRequest.IUpdate,
      },
    );
  typia.assert(approvedCancellation);
  // ---- Step 5: SuperAdministrator attempts force-refund on 'cancelled' item ----
  const superAdminConnection: api.IConnection = { host: connection.host };
  await authorize_super_administrator_join(superAdminConnection, {});
  // The force-refund must be rejected because the item is already in terminal 'cancelled' state
  await TestValidator.httpError(
    "force-refund rejected for cancelled order item",
    [400, 409, 422],
    async () => {
      await api.functional.eCommerceMall.superAdministrator.order_items.force_refund.create(
        superAdminConnection,
        { itemId: orderItem.id },
      );
    },
  );
}

