      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // Step A: First force-refund — should refund the item
  const firstRefund =
    await api.functional.eCommerceMall.administrator.orders.force_refund.forceRefund(
      adminConnection,
