        body: {} satisfies IECommerceMallOrder.IForceRefundRequest,
      },
    );
  typia.assert(refundResult);
  //---------------------------------------------------------------------------------
  // 9. Validate the force-refund response
  //---------------------------------------------------------------------------------
  // Both items were 'paid' (not terminal), so both should be refunded
  TestValidator.predicate("refundedItems has 2 items", () => {
    return refundResult.refundedItems.length === 2;
  });
  // No items should be skipped since none were in terminal state
  TestValidator.predicate("skippedItems is empty", () => {
    return refundResult.skippedItems.length === 0;
  });
  // Validate refunded item summaries
  const refundedIds = refundResult.refundedItems.map((item) => item.id).sort();
  const expectedIds = [paidItem1.id, paidItem2.id].sort();
  TestValidator.equals("refunded items match order items", refundedIds, expectedIds);
}

