      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
    data: await ArrayUtil.asyncMap(
      snapshots,
      ECommerceMallSellerProfileSnapshotAtSummaryTransformer.transform,
    ),
  };
}

