  const now = new Date().toISOString();
  if (category.parent_id === null) {
    const subcategories =
      await MyGlobal.prisma.e_commerce_mall_categories.findMany({
        where: { parent_id: props.categoryId, deleted_at: null },
        select: { id: true },
