export async function patchECommerceMallAdministratorCancellationRequests(props: {
  administrator: AdministratorPayload;
  body: IECommerceMallCancellationRequest.IRequest;
}): Promise<IPageIECommerceMallCancellationRequest.ISummary> {
  // Build base WHERE clause: exclude soft-deleted records
  const whereInput: Prisma.e_commerce_mall_cancellation_requestsWhereInput = {
    deleted_at: null,
  };
  // Apply search filter on reason text (uses gin_trgm index)
  if (props.body.search !== undefined) {
    whereInput.reason = {
      contains: props.body.search,
      mode: "insensitive",
    };
  }
  // Apply status filter (single or multiple statuses from array)
  if (props.body.status !== undefined) {
    whereInput.status = {
      in: props.body.status,
    };
  }
  // Apply customer ID filter
  if (props.body.customer_id !== undefined) {
    whereInput.e_commerce_mall_customer_id = props.body.customer_id;
  }
  // Apply seller ID filter
  if (props.body.seller_id !== undefined) {
    whereInput.e_commerce_mall_seller_id = props.body.seller_id;
  }
  // Apply order item ID filter
  if (props.body.order_item_id !== undefined) {
    whereInput.e_commerce_mall_order_item_id = props.body.order_item_id;
  }
  // Apply creation date range filter using ISO strings (no Date constructors)
  if (
    props.body.created_at_from !== undefined &&
    props.body.created_at_to !== undefined
  ) {
    whereInput.created_at = {
      gte: props.body.created_at_from,
