        status: "pending",
        orderItem: {
          productVariant: {
            product: {
              seller_id: sellerId,
            },
          },
        },
      },
    }),
  ]);
  return {
    totalProducts,
    totalOrderItems,
    pendingCancellationRequests,
    pendingRefundRequests,
  };
}

