  const item = await MyGlobal.prisma.e_commerce_mall_order_items.findUnique({
    where: { id: props.itemId },
    select: {
      id: true,
      status: true,
      quantity: true,
      e_commerce_mall_product_variant_id: true,
    },
  });
  if (item === null) {
    throw new HttpException("Order item not found", 404);
