import { postECommerceMallAdministratorCustomersCustomerIdUnban } from "../../../../providers/postECommerceMallAdministratorCustomersCustomerIdUnban";

@Controller("/eCommerceMall/administrator/customers")
export class EcommercemallAdministratorCustomersController {
  /**
   * Search and list customer accounts with filtering and pagination.
   *
   * This operation returns a paginated list of customer accounts based on the provided search criteria. Results include each customer's email, account creation date, ban status, and associated profile information (display name, phone number). Supports filtering by email, registration date range, ban status, and account status (active vs deleted). Results are sorted by creation date (newest first) by default.
   *
   * Pagination is handled through cursor or offset-based parameters in the request body, with each response containing metadata about the total number of matching records and available pages for efficient client-side navigation.
   *
   * @param connection
   * @param body Search criteria for filtering customer accounts, including email search, registration date range, ban status filter, account status filter, and pagination parameters (page, limit).
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor administrator
   * @x-autobe-specification Query the e_commerce_mall_customers table with optional LEFT JOIN to e_commerce_mall_customer_profiles. Apply search/filter criteria from the request body including email search (ILIKE/partial match), registration date range (created_at), ban status (banned_at IS NULL / IS NOT NULL), and account status (deleted_at IS NULL for active accounts, IS NOT NULL for deleted accounts). Support pagination with page/limit parameters and sorting by created_at, email, or banned_at. Exclude password_hash from results. Default sort is created_at DESC (newest first). Return paginated response with total count, page info, and array of customer summary records.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @AdministratorAuth()
    administrator: AdministratorPayload,
    @TypedBody()
    body: IECommerceMallCustomer.IRequest,
  ): Promise<IPageIECommerceMallCustomer.ISummary> {
    try {
      return await patchECommerceMallAdministratorCustomers({
        administrator,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a single customer account by its unique identifier.
   *
   * This endpoint provides administrators with detailed customer account information for oversight purposes. The response includes the customer's email address, account creation and update timestamps, ban status, and the associated customer profile (display name and phone number).
   *
   * Account deletion and ban status are reflected through the deleted_at and banned_at fields respectively — a non-null deleted_at indicates the customer has deleted their account, while a non-null banned_at indicates an administrator has banned the account. The response includes both active and soft-deleted/banned accounts so administrators have full visibility into all account states. Addresses are not included in this response; use the dedicated address endpoint for address management.
   *
   * This operation is restricted to administrators. Regular customers cannot access other customers' account data due to privacy boundaries.
   *
   * @param connection
   * @param customerId Unique identifier (UUID) of the customer account to retrieve.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor administrator
   * @x-autobe-specification Query the e_commerce_mall_customers table by id (UUID primary key). Include the related e_commerce_mall_customer_profiles record via the 1:1 relation on e_commerce_mall_customer_id. Exclude the password_hash field from the response for security. Do NOT filter by deleted_at or banned_at — administrators need visibility into all account states including soft-deleted and banned accounts. Return a 404 Not Found error with appropriate error message if no customer matches the given customerId.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":customerId")
  public async at(
    @AdministratorAuth()
    administrator: AdministratorPayload,
    @TypedParam("customerId")
    customerId: string & tags.Format<"uuid">,
  ): Promise<IECommerceMallCustomer> {
    try {
      return await getECommerceMallAdministratorCustomersCustomerId({
        administrator,
        customerId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Ban a customer account, immediately revoking their ability to log into the platform.
   *
   * This operation is restricted to administrators. When a customer is banned, their existing orders continue processing normally and their existing reviews remain visible on product pages. The customer's account and all associated data (orders, reviews, addresses) are preserved in the system — only login access is revoked.
   *
   * A banned customer cannot log in until an administrator unbans them. Attempting to log in while banned returns a rejection notice indicating the account has been banned. To restore access, use the unban operation which clears the ban.
   *
   * @param connection
   * @param customerId The unique identifier (UUID) of the customer account to ban.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor administrator
   * @x-autobe-specification Validate that the requesting actor is an administrator with ban authority. Look up the customer by {customerId} UUID — return 404 if not found. If the customer is already banned (banned_at is not null), the operation is idempotent: return the current state as success. If the customer account is deleted (deleted_at is not null), reject with an appropriate error since deleted accounts cannot be banned. On success, set banned_at to the current timestamp on the e_commerce_mall_customers record and return the updated customer entity.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post(":customerId/ban")
  public async ban(
    @AdministratorAuth()
    administrator: AdministratorPayload,
    @TypedParam("customerId")
    customerId: string & tags.Format<"uuid">,
  ): Promise<IECommerceMallCustomer> {
    try {
      return await postECommerceMallAdministratorCustomersCustomerIdBan({
        administrator,
        customerId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Unban a customer account by clearing their ban timestamp.
   *
   * When an administrator initiates the unban action on a banned customer account, the system removes the customer's ban, restoring their ability to log into the platform using their registered email and password. The customer's existing orders continue to process normally, and their existing reviews remain visible on product pages. All associated customer data is preserved intact.
   *
   * This operation requires administrator-level authorization. Only accounts with administrator privileges can unban customer accounts.
   *
   * @param connection
   * @param customerId The unique identifier (UUID) of the customer account to unban.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor administrator
   * @x-autobe-specification Query e_commerce_mall_customers table by customerId (UUID). Verify the customer record exists - throw 404 if not found. Verify the customer is currently banned (banned_at is not null) - throw 422 with message 'Customer is not currently banned' if banned_at is null. Set banned_at to null to lift the ban. Update updated_at timestamp. Return the full IECommerceMallCustomer record with the cleared ban state.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post(":customerId/unban")
  public async unban(
    @AdministratorAuth()
    administrator: AdministratorPayload,
    @TypedParam("customerId")
    customerId: string & tags.Format<"uuid">,
  ): Promise<IECommerceMallCustomer> {
    try {
      return await postECommerceMallAdministratorCustomersCustomerIdUnban({
        administrator,
        customerId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

