   * @param connection
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification Validate that the authenticated seller exists and has approval_status 'rejected'. If the seller does not exist or approval_status is not 'rejected', reject the operation with an appropriate error. Create a new e_commerce_mall_seller_approval_requests record with: seller_id set to the authenticated seller's ID from the auth context, status 'pending', created_at and updated_at set to the current timestamp. reviewer_id, rejection_reason, and reviewed_at remain null. Return the newly created approval request record including the generated id and timestamps.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async create(
    @SellerAuth()
    seller: SellerPayload,
  ): Promise<IECommerceMallSellerApprovalRequest> {
    try {
      return await postECommerceMallSellerApprovalRequests({
