  /**
   * Retrieve the product-variant snapshot for a specific order item.
   *
   * The snapshot is an immutable historical record created at the time of order placement, preserving the exact product name, description, base price, variant SKU, variant option values, and variant price that were presented to the customer at checkout. This snapshot persists even if the seller later edits or deletes the original product or variant, ensuring a permanent audit trail for order histories, dispute resolution, and financial record-keeping.
   *
   * Accessible by the customer who placed the order, the seller who fulfilled the item, and platform administrators for order review purposes.
   *
   * @param connection
   * @param itemId Unique identifier (UUID) of the order item whose product-variant snapshot is being retrieved. Each order item has exactly one snapshot, created at order placement time.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Query the e_commerce_mall_order_item_snapshots table filtering by e_commerce_mall_order_item_id matching the provided itemId parameter. Since the relationship is 1:1 (enforced by unique constraint on e_commerce_mall_order_item_id), the query will return at most one record.
   *
   * Authorization:
   * - The requesting customer must own the parent order containing this order item.
   * - The requesting seller must own the product variant referenced by the order item.
   * - Administrators can view snapshots for any order item.
   * - Return 404 Not Found if the order item does not exist or has no snapshot (snapshot is always created at order placement, so presence implies a valid, paid order item).
   * - Return 403 Forbidden if the requester lacks access to the order item.
   *
   * The snapshot is immutable — no modification or deletion allowed per business rules.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get()
  public async at(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("itemId")
    itemId: string & tags.Format<"uuid">,
  ): Promise<IECommerceMallOrderItemSnapshot> {
    try {
      return await getECommerceMallCustomerOrderItemsItemIdProductSnapshot({
        customer,
        itemId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

