import { IECommerceMallCategory } from "../../../../../api/structures/IECommerceMallCategory";
import { CustomerAuth } from "../../../../../decorators/CustomerAuth";
import { CustomerPayload } from "../../../../../decorators/payload/CustomerPayload";
import { patchECommerceMallCustomerCategoriesHierarchy } from "../../../../../providers/patchECommerceMallCustomerCategoriesHierarchy";

@Controller("/eCommerceMall/customer/categories/hierarchy")
export class EcommercemallCustomerCategoriesHierarchyController {
  /**
   * Search for and retrieve the complete category hierarchy tree.
   *
   * Returns all non-deleted categories organized in a two-level parent-child structure: top-level categories (categories with no parent) each containing their nested subcategories. Soft-deleted categories (those with a deleted_at timestamp) are excluded from the result.
   *
   * The hierarchy enables customers to browse the product catalog by category and navigate from broad groupings down to specific product types. Administrators also use this endpoint to view and manage the category structure.
   *
   * Optional name-based filtering allows narrowing the result to categories whose names partially match the search term. When a filter matches a subcategory, its parent top-level category is included in the response to preserve the hierarchy context. Categories are ordered by creation timestamp within each hierarchy level.
   *
   * @param connection
   * @param body Search and filter criteria for retrieving the category hierarchy. Supports an optional name search term that performs case-insensitive partial matching against category names.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Query e_commerce_mall_categories WHERE deleted_at IS NULL. Segregate rows into top-level (parent_id IS NULL) and subcategories (parent_id IS NOT NULL). If a name search filter is provided in the request body, apply case-insensitive partial matching on the name column. When a subcategory matches the name filter, include its parent top-level category in the result. Build the response tree by nesting matching subcategories under their parent using parent_id matching. Order top-level categories by created_at ASC, order subcategories under each parent by created_at ASC. Handle edge cases: empty result returns hierarchy with empty arrays; all categories soft-deleted returns empty structure; category with no subcategories returns an empty subcategories array for that node.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async search(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedBody()
    body: IECommerceMallCategory.IHierarchyRequest,
  ): Promise<IECommerceMallCategory.IHierarchy> {
    try {
      return await patchECommerceMallCustomerCategoriesHierarchy({
        customer,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

