import { TypedParam, TypedRoute } from "@nestia/core";
import { Controller } from "@nestjs/common";
import typia from "typia";

import { IECommerceMallOrder } from "../../../../../api/structures/IECommerceMallOrder";
import { CustomerAuth } from "../../../../../decorators/CustomerAuth";
import { CustomerPayload } from "../../../../../decorators/payload/CustomerPayload";
import { getECommerceMallCustomerOrdersOrderCodeCancellableItems } from "../../../../../providers/getECommerceMallCustomerOrdersOrderCodeCancellableItems";

@Controller("/eCommerceMall/customer/orders/:orderCode/cancellable-items")
export class EcommercemallCustomerOrdersCancellable_itemsController {
  /**
   * Retrieve all order items within a specified order that are eligible for cancellation.
   *
   * This endpoint returns only the items in "paid" status — meaning payment has been completed and the items have not yet been shipped by the seller. Items in "shipped", "delivered", "cancelled", or "refunded" status are excluded from the results. Cancellation is handled per individual order item (not per entire order), allowing customers to selectively cancel specific items while others continue processing normally.
   *
   * The response includes product name, variant options, quantity, unit price, and subtotal from the purchase-time snapshots for accurate historical reference. If no items are eligible for cancellation, an empty array is returned.
   *
   * @param connection
   * @param orderCode The unique order code assigned at order creation, used as a human-readable identifier for order lookup (global scope).
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Query the e_commerce_mall_orders table by the unique `code` field to find the order. Verify the order belongs to the authenticated customer. Join with e_commerce_mall_order_items filtered by status = 'paid'. For each paid order item, join with the order item's product-variant snapshot (e_commerce_mall_order_item_snapshots) to retrieve historical product name, variant SKU, variant options label, and unit price at purchase time. Return the array of eligible items sorted by order item creation date (oldest first). If the order code does not exist or does not belong to the requesting customer, return 404 Not Found. If no items are eligible for cancellation, return an empty array (200 OK). Also include the order item ID in each response element so the customer can reference it when creating cancellation requests.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get()
  public async cancellable(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("orderCode")
    orderCode: string,
  ): Promise<IECommerceMallOrder.ICancellableItem> {
    try {
      return await getECommerceMallCustomerOrdersOrderCodeCancellableItems({
        customer,
        orderCode,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

